var i=100;var a=[{id:`cooking-100-01`,theoryId:100,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why can mushrooms brown better when cooked in uncrowded batches?`,ua:`Чому гриби краще підрум’янюються невеликими партіями?`},explanation:{en:`Dryer contact surfaces reach browning temperatures more readily.`,ua:`Сухіша контактна поверхня легше досягає температур підрум’янення.`},options:[{id:`a`,text:{en:`Released moisture evaporates rather than collecting in the pan`,ua:`Виділена волога випаровується, а не накопичується`}},{id:`b`,text:{en:`Mushrooms contain no water`,ua:`У грибах немає води`}},{id:`c`,text:{en:`Crowding automatically raises surface temperature`,ua:`Переповнення автоматично підвищує температуру поверхні`}}],answer:{optionIds:[`a`]}},{id:`cooking-100-02`,theoryId:100,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`An unknown wild mushroom is safe to eat if it smells pleasant.`,ua:`Невідомий дикорослий гриб безпечний, якщо приємно пахне.`},explanation:{en:`Smell does not establish species identity or edibility.`,ua:`Запах не підтверджує вид гриба чи його їстівність.`},answer:{value:!1}},{id:`cooking-100-03`,theoryId:100,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match mushroom observations to actions.`,ua:`Поєднайте ознаки грибів із діями.`},explanation:{en:`Preparation and identification are separate aspects of mushroom safety.`,ua:`Приготування та визначення виду — різні питання безпеки грибів.`},leftItems:[{id:`l1`,text:{en:`Trusted cultivated mushroom`,ua:`Гриб від надійного виробника`}},{id:`l2`,text:{en:`Crowded wet pan`,ua:`Переповнена волога сковорода`}},{id:`l3`,text:{en:`Unidentified wild specimen`,ua:`Невідомий дикорослий гриб`}}],rightItems:[{id:`r3`,text:{en:`Do not eat it`,ua:`Не їсти його`}},{id:`r2`,text:{en:`Cook in smaller batches`,ua:`Готувати меншими партіями`}},{id:`r1`,text:{en:`Use after appropriate handling`,ua:`Використати після належної підготовки`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-100-04`,theoryId:100,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Your mushrooms steam in a pool of released liquid. What helps browning?`,ua:`Гриби тушкуються у власному соку. Що допоможе підрум’яненню?`},explanation:{en:`More surface area per mushroom makes evaporation easier.`,ua:`Більша площа нагрівання на одну порцію грибів полегшує випаровування.`},options:[{id:`a`,text:{en:`Use a wider hot pan and smaller batches`,ua:`Взяти ширшу гарячу сковороду й менші партії`}},{id:`b`,text:{en:`Pile more mushrooms into the same pan`,ua:`Додати ще більше грибів у той самий посуд`}},{id:`c`,text:{en:`Add a deep layer of cold water`,ua:`Долити багато холодної води`}}],answer:{optionIds:[`a`]}},{id:`cooking-100-05`,theoryId:100,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which mushroom safety statement is wrong?`,ua:`Яке твердження про безпечність грибів хибне?`},explanation:{en:`Many mushroom toxins are not reliably destroyed by ordinary cooking.`,ua:`Багато грибних токсинів не руйнуються під час звичайного приготування.`},options:[{id:`a`,text:{en:`Wild specimens need expert identification`,ua:`Дикорослі гриби потребують експертного визначення`}},{id:`b`,text:{en:`Trusted retail sources lower identification risk`,ua:`Надійні магазини зменшують ризик помилки у виді`}},{id:`c`,text:{en:`Cooking makes every toxic wild mushroom harmless`,ua:`Варіння робить будь-який отруйний дикорослий гриб нешкідливим`}}],answer:{optionIds:[`c`]}},{id:`cooking-100-06`,theoryId:100,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`What are sound choices when handling mushrooms?`,ua:`Які рішення правильні під час роботи з грибами?`},explanation:{en:`Species identification, quality and heat management address different concerns.`,ua:`Визначення виду, якість і контроль нагрівання стосуються різних аспектів.`},options:[{id:`a`,text:{en:`Buy identifiable cultivated mushrooms from reputable sellers`,ua:`Купувати визначені культивовані гриби у надійних продавців`}},{id:`b`,text:{en:`Cook in batches for browning`,ua:`Для підрум’янення готувати партіями`}},{id:`c`,text:{en:`Taste unidentified wild mushrooms to see if safe`,ua:`Куштувати невідомі дикорослі гриби для перевірки`}},{id:`d`,text:{en:`Discard spoiled slimy mushrooms`,ua:`Викидати зіпсовані слизькі гриби`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var n={theoryId:100,exercises:a};export{n as default,a as exercises,i as theoryId};